def kthSmallestProduct(nums1, nums2, k):
    # Helper: count pairs with product ≤ x
    def count_leq(x):
        count = 0
        for a in nums1:
            if a == 0:
                if x >= 0:
                    count += len(nums2)
                # else, product cannot be ≤ negative x
            elif a > 0:
                # For positive a, product increases as nums2 increases
                # Find rightmost index where a * nums2[j] ≤ x
                l, r = 0, len(nums2)
                while l < r:
                    m = (l + r) // 2
                    if a * nums2[m] <= x:
                        l = m + 1
                    else:
                        r = m
                count += l
            else:  # a < 0
                # For negative a, product decreases as nums2 increases
                l, r = 0, len(nums2)
                while l < r:
                    m = (l + r) // 2
                    if a * nums2[m] <= x:
                        r = m
                    else:
                        l = m + 1
                count += len(nums2) - l
        return count

    # Binary search on product value
    left, right = -10**10, 10**10
    ans = 0
    while left <= right:
        mid = (left + right) // 2
        cnt = count_leq(mid)
        if cnt >= k:
            ans = mid
            right = mid - 1
        else:
            left = mid + 1
    return ans
